100	```javascript
101	// Words whose trailing period does not end a sentence. Compared lower-case and
102	// without any opening bracket or quote. "U.S.A." style initialisms are not
103	// listed: they usually do end a sentence when they come last, and guessing
104	// otherwise would trade one error for another.
105	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
106	
107	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
108	// only where whitespace or the end of the text follows. Requiring that keeps
109	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
110	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
111	
112	function endsWithAbbreviation(before) {
113	  const last = before.match(/(\S+)$/);
114	  if (last === null) {
115	    return false;
116	  }
117	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
118	  return ABBREVIATIONS.has(word);
119	}
120	
121	/**
122	 * Count the sentences in a piece of text.
123	 *
124	 * A sentence is a stretch of text containing at least one word and ending at a
125	 * terminator run, or at the end of the text. A lone period after a known
126	 * abbreviation does not end a sentence.
127	 *
128	 * @param {string} text
129	 * @returns {number}
130	 */
131	function sentenceCount(text) {
132	  assertText('sentenceCount', text);
133	  let count = 0;
134	  let start = 0;
135	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
136	    const before = text.slice(start, match.index);
137	    if (match[1] === '.' && endsWithAbbreviation(before)) {
138	      continue;
139	    }
140	    if (tokenize(before).length > 0) {
141	      count += 1;
142	    }
143	    start = match.index + match[0].length;
144	  }
145	  if (tokenize(text.slice(start)).length > 0) {
146	    count += 1;
147	  }
148	  return count;
149	}
150	
151	module.exports = { wordCount, sentenceCount };
152	```
